11	func runCLI(t *testing.T, file string, args ...string) (stdout, stderr string, code int) {
12		t.Helper()
13		var out, errb bytes.Buffer
14		full := append([]string{"-f", file}, args...)
15		code = run(full, &out, &errb)
16		return out.String(), errb.String(), code
17	}
