	}
	if msg := err.Error(); !strings.Contains(msg, "内容损坏") ||
		!strings.Contains(msg, "s1") || !strings.Contains(msg, "w1") {
		t.Fatalf("错误应点名 s1 的有效免修 w1 缺少依据，得到：%v", err)
	}
	got, readErr := os.ReadFile(path)
	if readErr != nil {
		t.Fatal(readErr)
	}
	if string(got) != string(raw) {
		t.Fatal("拒绝读取不得改写原文件")
	}
}

