				"字符串中高位代理项转义 \\u%04X 后紧跟的不是低位代理项转义，代理项没有成对出现", r),
			offset: i,
		}
	}
	return next + 6, nil
}

// jsonHex4 读取 p[j:j+4] 的四个十六进制数位并拼成数值；不足四位或含非
// 十六进制字符时返回 ok=false。
func jsonHex4(p []byte, j int) (int, bool) {
	if j+4 > len(p) {
		return 0, false
	}
	v := 0
	for k := 0; k < 4; k++ {
		var d int
		switch c := p[j+k]; {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			return 0, false
		}
		v = v<<4 | d
	}
	return v, true
}

