package credit

import (
	"fmt"
	"unicode/utf8"
)

// invalidUnicodeError 表示记录文件的 JSON 字符串原始内容无法还原为合法
// Unicode 文字：要么字符串里直接写出的字节不是合法 UTF-8，要么 \uXXXX
// 转义里出现了未配对的代理项（孤立的高/低代理项、两个高位代理项相连等）。
type invalidUnicodeError struct {
	kind   string
	offset int
}

func (e *invalidUnicodeError) Error() string {
	return fmt.Sprintf("%s（字节偏移 %d 附近）", e.kind, e.offset)
}

// scanValidUnicode 在不做任何字符替换的前提下，按原始字节扫描第一份完整
// JSON 值中出现的每一个字符串——字段名与字段值同等对待——确认其内容都能
// 还原为合法 Unicode 文字：
//
//   - 字符串中直接写出的字节必须构成合法 UTF-8；
//   - \uXXXX 转义里，高位代理项（U+D800–U+DBFF）后必须紧跟一个低位代理项
//     转义（U+DC00–U+DFFF）；单独的低位代理项、高位代理项后没有低位代理项、
//     两个高位代理项连在一起，都不是某个普通字符，一律拒绝。
//
// 背景：encoding/json 会把上述两种情形静默替换成 U+FFFD 后照常返回，
// json.Valid 也把这样的输入判为“有效”。替换会改变学生编号、课程名称与
// 免修依据的原意，绝不能拿替换后的文字继续查询、核对或登记，因此这一检查
// 必须在标准库解码之前按原始字节进行。
//
// 本函数只管 Unicode 文字这一件事，不负责 JSON 语法：遇到未结束的字符串、
// 残缺或非法转义时即结束本次扫描（放行），由调用方随后的标准 JSON 解析判
// 为语法损坏。语法合法的文件中转义必然完整，因此所有“会被标准库接受、但
// 文字已被替换”的情形在这里都逃不掉；而本身语法已损坏的文件也不会因为
// 本函数提前返回而被放过。
//
// 用户真正写入的 U+FFFD（直接写出的 UTF-8 字节 EF BF BD 或 � 转义）
// 是合法文字；直接写出的补充平面字符、完整的高低代理项对、转义表达的控制
// 字符都按原意保留，本函数既不替换也不改写。只扫描第一份完整顶层值，与
// 重复字段扫描的范围一致，完整记录之后的多余内容由调用方另行检查。
func scanValidUnicode(p []byte) error {
	i := 0
scan:
	for i < len(p) {
		switch p[i] {
		case ' ', '\t', '\r', '\n':
			i++
		default:
			break scan
		}
	}
	if i >= len(p) {
		return nil // 空输入交由后续解析报错
	}
	// 顶层标量（数字、true/false/null 或语法垃圾）内部不含字符串，直接
	// 放行：合法标量没有可检查的文字，其余情形由后续 JSON 解析拒绝。
	if c := p[i]; c != '{' && c != '[' && c != '"' {
		return nil
	}
	depth := 0
	for i < len(p) {
		switch p[i] {
		case ' ', '\t', '\r', '\n':
			i++
		case '{', '[':
			depth++
			i++
		case '}', ']':
			depth--
			i++
			if depth == 0 {
				return nil // 唯一的顶层值已完整结束
			}
		case '"':
			next, err := scanStringUnicode(p, i+1)
			if err != nil {
				return err
			}
			i = next
			if depth == 0 {
				return nil // 顶层字符串值
			}
		default:
			// 结构字符、逗号、冒号、数字与字面量都不可能含字符串文字。
			i++
		}
	}
	return nil
}

// scanStringUnicode 校验从开引号之后开始的一段 JSON 字符串原始内容，
// 返回越过闭引号后的位置。字符串未正常结束或转义残缺/非法时返回
// len(p) 且不报错——这些属于 JSON 语法错误，交由调用方的标准解析拒绝。
func scanStringUnicode(p []byte, i int) (int, error) {
	for i < len(p) {
		c := p[i]
		switch {
		case c == '"':
			return i + 1, nil
		case c == '\\':
			if i+1 >= len(p) {
				return len(p), nil // 残缺转义：语法阶段拒绝
			}
			switch p[i+1] {
			case '"', '\\', '/', 'b', 'f', 'n', 'r', 't':
				i += 2
			case 'u':
				next, err := scanUnicodeEscape(p, i)
				if err != nil {
					return 0, err
				}
				if next < 0 {
					return len(p), nil // \u 转义不完整：语法阶段拒绝
				}
				i = next
			default:
				return len(p), nil // 非法转义：语法阶段拒绝
			}
		case c < 0x20:
			i++ // 未转义控制字符：语法阶段拒绝
		case c < utf8.RuneSelf:
			i++
		default:
			r, size := utf8.DecodeRune(p[i:])
			if r == utf8.RuneError && size == 1 {
				return 0, &invalidUnicodeError{
					kind:   "字符串中直接写入了不是合法 UTF-8 的字节，无法还原为 Unicode 文字",
					offset: i,
				}
			}
			i += size
		}
	}
	return len(p), nil // 字符串未结束：语法阶段拒绝
}

// scanUnicodeEscape 处理位于 p[i] 的一个 \uXXXX 转义，返回越过该转义后的
// 位置；返回负值表示转义不完整（交由语法检查）。高位代理项必须与紧随其后
// 的低位代理项转义配对，否则按无效文字报错。
func scanUnicodeEscape(p []byte, i int) (int, error) {
	r, ok := jsonHex4(p, i+2)
	if !ok {
		return -1, nil
	}
	next := i + 6
	switch {
	case r < 0xD800 || r > 0xDFFF:
		return next, nil // 普通 BMP 字符（U+FFFD 也在此列，属合法文字）
	case r >= 0xDC00:
		return 0, &invalidUnicodeError{
			kind:   fmt.Sprintf("字符串中出现未配对的低位代理项转义 \\u%04X，不能当作普通字符", r),
			offset: i,
		}
	}
	// 高位代理项：后面必须紧跟一个 \uXXXX，且其值在低位代理项区间。
	if next+6 > len(p) || p[next] != '\\' || p[next+1] != 'u' {
		return 0, &invalidUnicodeError{
			kind: fmt.Sprintf(
				"字符串中高位代理项转义 \\u%04X 后没有紧跟对应的低位代理项转义，不能当作普通字符", r),
			offset: i,
		}
	}
	low, ok := jsonHex4(p, next+2)
	if !ok {
		return -1, nil // 后一个 \u 转义本身残缺：语法阶段拒绝
	}
	if low < 0xDC00 || low > 0xDFFF {
		return 0, &invalidUnicodeError{
			kind: fmt.Sprintf(
				"字符串中高位代理项转义 \\u%04X 后紧跟的不是低位代理项转义（得到 \\u%04X），代理项没有成对出现",
				r, low),
			offset: i,
		}
	}
	return next + 6, nil
}

// jsonHex4 读取 p[j:j+4] 的四个十六进制数位并拼成数值；不足四位或含非
// 十六进制字符时返回 ok=false。
func jsonHex4(p []byte, j int) (int, bool) {
	if j+4 > len(p) {
		return 0, false
	}
	v := 0
	for k := 0; k < 4; k++ {
		var d int
		switch c := p[j+k]; {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			return 0, false
		}
		v = v<<4 | d
	}
	return v, true
}

package credit

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// 本文件回归“记录文件中的 JSON 字符串必须能按原始内容还原为合法 Unicode
// 文字”：直接写入的非法 UTF-8 字节与未配对的代理项转义不能被标准库替换成
// U+FFFD 后继续使用；问题无论出在字段名还是字段值、出在哪条记录，整份
// 文件都判为内容损坏，且原文件逐字节保留。用户真正写入的 U+FFFD、直接
// 写出的补充平面字符与完整高低代理项对仍按合法文字正常读取。

func TestScanValidUnicodeAcceptsLegal(t *testing.T) {
	cases := map[string]string{
		"普通中文":            `{"id":"学生","name":"高等数学"}`,
		"直接写入的补充平面字符":     `{"id":"😀","name":"𠀀𩰲"}`,
		"完整高低代理项转义对":      `{"id":"a𐀀b"}`,
		"非BMP中文字符代理项对":    `{"name":"𠀀"}`,
		"用户写入的U+FFFD转义":   `{"id":"a�b"}`,
		"用户直接写出的替换字符":     "{\"id\":\"a�b\"}",
		"转义控制字符":          `{"basis":"a\tb\nc\rd\u0000e"}`,
		"其他常见转义":          `{"a":"\\\/\"\b\f\r\n\t"}`,
		"空字符串与空输入":         `{"":"","x":[]}`,
		"深层嵌套":            `{"a":[{"b":[{"c":"中文😀𐀀"}]}]}`,
		"记录前后空白":          "\n\t " + `{"id":"s"}` + "\r\n",
		"顶层字符串":           `"s1"`,
		"顶层数字":            `42`,
		"首份值之后的非法字节不扫描": `{"id":"s1"}{"id":"xff"}`,
	}
	for name, in := range cases {
		t.Run(name, func(t *testing.T) {
			if err := scanValidUnicode([]byte(in)); err != nil {
				t.Fatalf("合法文字不应被拒绝：%v（输入 %q）", err, in)
			}
		})
	}
}

func TestScanValidUnicodeRejectsInvalid(t *testing.T) {
	cases := map[string]string{
		"值中直接写入非法UTF8字节":   `{"id":"s` + "\xff" + `"}`,
		"字段名中直接写入非法UTF8字节": `{"s` + "\xff" + `":1}`,
		"课程名称含截断的三字节序列":   `{"name":"数` + "\xe6\x95" + `"}`,
		"依据中出现孤立续接字节":      `{"basis":"a` + "\x80" + `b"}`,
		"孤立高位代理项":          `{"id":"a\uD800b"}`,
		"孤立低位代理项":          `{"id":"a\uDC00b"}`,
		"两个高位代理项相连":        `{"id":"a\uD800\uD800b"}`,
		"高位代理项后跟普通BMP转义":   `{"id":"a\uD800Ab"}`,
		"高位代理项后字符串结束":      `{"id":"a\uD800"}`,
		"低位代理项位于字段名":       `{"a\uDC00":1}`,
		"高位代理项大写写法":        `{"id":"\uDABC"}`,
		"代理项对跨在两个不同字符串":   `{"a":"\uD800","b":"\uDC00"}`,
	}
	for name, in := range cases {
		t.Run(name, func(t *testing.T) {
			if err := scanValidUnicode([]byte(in)); err == nil {
				t.Fatalf("无效 Unicode 文字必须报错（输入 %q）", in)
			}
		})
	}
}

// 残缺或语法本身就不合法的文件不应在 Unicode 扫描阶段被误判（也不应被
// 放过）：扫描直接结束，由随后的标准 JSON 解析按语法损坏拒绝。
func TestScanValidUnicodeLeavesSyntaxErrorsToParser(t *testing.T) {
	cases := map[string]string{
		"字符串未结束":     `{"id":"s1`,
		"转义残缺":       `{"id":"s1\uD80"}`,
		"非法转义":       `{"id":"a\x"}`,
		"裸控制字符":      "{\"id\":\"a\x01b\"}",
		"对象缺右括号":     `{"id":"s1"`,
		"高位转义后跟半个u":  `{"id":"a\uD800\u"}`,
	}
	for name, in := range cases {
		t.Run(name, func(t *testing.T) {
			if err := scanValidUnicode([]byte(in)); err != nil {
				t.Fatalf("语法问题不应由 Unicode 扫描报错，得到 %v（输入 %q）", err, in)
			}
		})
	}
}

// TestLoadRejectsInvalidUnicode 端到端覆盖 Load：各种无效 Unicode 情形都
// 必须让整份记录判为内容损坏——错误点名文件、说明存在无效的 Unicode 文字、
// 标记文件已存在，且原文件每个字节原样保留，不返回任何可用于业务的 store。
func TestLoadRejectsInvalidUnicode(t *testing.T) {
	wrap := func(inner string) string {
		return `{"version":1,` + inner + `}` + "\n"
	}
	cases := map[string]string{
		"学生编号含非法字节": wrap(`"students":[{"id":"s1\xff"}]`),
		"课程名称含非法字节": wrap(`"courses":[{"id":"c1","name":"数` + "\xe6" + `","credit":4,"open":true}]`),
		"有效免修依据含非法字节": wrap(
			`"students":[{"id":"s1"}],`+
				`"courses":[{"id":"c1","name":"数学","credit":4,"open":true}],`+
				`"requirements":[{"id":"r1","student":"s1","course":"c1"}],`+
				`"waivers":[{"id":"w1","student":"s1","req":"r1","basis":"获奖\xff","status":"approved"}]`),
		"已拒绝免修依据含孤立代理项": wrap(
			`"students":[{"id":"s1"}],`+
				`"waivers":[{"id":"w1","student":"s1","req":"r9","basis":"\uD800","status":"rejected","reason":"x"}]`),
		"未涉及课程名称含孤立低位代理项": wrap(
			`"students":[{"id":"s1"}],`+
				`"courses":[{"id":"c9","name":"\uDC00","credit":4,"open":true}]`),
		"字段名含孤立代理项": wrap(`"students":[{"id":"s1","\uD800":"x"}]`),
		"编号含两个高位代理项": wrap(`"students":[{"id":"s\uD800\uD800"}]`),
		"高位代理项后跟普通字符": wrap(`"students":[{"id":"\uD800A"}]`),
	}
	for name, content := range cases {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "records.json")
			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
				t.Fatal(err)
			}
			s, existed, err := Load(path)
			if err == nil {
				t.Fatalf("含无效 Unicode 的记录必须拒绝读取，却得到 store=%v", s)
			}
			if !existed {
				t.Fatal("损坏文件应标记为已存在")
			}
			msg := err.Error()
			for _, want := range []string{path, "内容损坏", "无效的 Unicode"} {
				if !strings.Contains(msg, want) {
					t.Fatalf("错误信息应包含 %q，得到：%v", want, err)
				}
			}
			got, readErr := os.ReadFile(path)
			if readErr != nil {
				t.Fatal(readErr)
			}
			if string(got) != content {
				t.Fatalf("拒绝读取不得改动原文件\nwant=%q\n got=%q", content, got)
			}
		})
	}
}

// TestLoadAcceptsLegalUnicode 合法文字保持原有兼容行为：中文、直接写入的
// 补充平面字符、完整代理项转义对、用户自己写入的 U+FFFD 与转义控制字符都
// 按原意读取，编号归属、依据原文与核对结果不受影响。
func TestLoadAcceptsLegalUnicode(t *testing.T) {
	content := `{
  "version": 1,
  "courses": [
    {"id": "c1", "name": "高等数学😀", "credit": 4, "open": true},
    {"id": "c2", "name": "辅修课𐀀", "credit": 3, "open": true}
  ],
  "students": [
    {"id": "s1"},
    {"id": "s2�"}
  ],
  "requirements": [
    {"id": "r1", "student": "s1", "course": "c1"},
    {"id": "r2", "student": "s1", "course": "c2"}
  ],
  "enrollments": [
    {"id": "e1", "student": "s1", "req": "r1", "term": "2024春\t上",
     "result": "passed", "resultSeq": 1}
  ],
  "waivers": [
    {"id": "w1", "student": "s1", "req": "r2", "basis": "竞赛 获奖\u0000材料", "status": "approved"}
  ],
  "nextResultSeq": 1
}
`
	path := filepath.Join(t.TempDir(), "records.json")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	s, existed, err := Load(path)
	if err != nil || !existed {
		t.Fatalf("合法 Unicode 记录应正常读取：existed=%v err=%v", existed, err)
	}
	if c := s.Course("c2"); c == nil || c.Name != "辅修课𐀀" {
		t.Fatalf("完整代理项对应按补充平面字符读取，得到 %+v", c)
	}
	if st := s.Student("s2�"); st == nil {
		t.Fatal("用户自己写入的 U+FFFD 是合法编号，必须照常读取")
	}
	if s.Student("s2") != nil {
		t.Fatal("含 U+FFFD 的编号不得与其他编号混淆")
	}
	w := s.Waiver("s1", "w1")
	if w == nil || w.Basis != "竞赛 获奖\x00材料" {
		t.Fatalf("转义控制字符与依据原文应原样保留，得到 %+v", w)
	}
	if rep := s.CheckStudent("s1"); rep.TotalCredits != 7 {
		t.Fatalf("合法记录核对结果应保持原样（7 学分），得到 %+v", rep)
	}
}

// TestLoadInvalidUnicodeNotMistakenForEmpty 含无效 Unicode 的文件绝不能被
// 当作空记录：Load 必须返回错误且 existed=true，调用方因此不会覆盖写回。
func TestLoadInvalidUnicodeNotMistakenForEmpty(t *testing.T) {
	path := filepath.Join(t.TempDir(), "records.json")
	content := `{"students":[{"id":"s1\xff"}]}`
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	s, existed, err := Load(path)
	if err == nil || s != nil {
		t.Fatalf("无效 Unicode 文件不能读出 store：s=%v err=%v", s, err)
	}
	if !existed {
		t.Fatal("必须报告文件已存在，不能当作不存在的空记录")
	}
}

